---@class UIMain_SwitchBtn
---@field catPanel      UnityEngine.RectTransform
---@field humanPanel    UnityEngine.RectTransform
local UIMain_SwitchBtn = Class('UIMain_SwitchBtn')


-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local QuestUtils = import('Game.DreamSpace.Quest.QuestUtils')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters

local SwitchablePlayerController = CS.Game.CharacterController.SwitchablePlayerController
local RoleMorphologyType = CS.Game.RoleMorphologyType

local GameContants = CS.Game.GameContants

local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace


-- ========================================================

local CatDefault    = "ActionDreamlandMainChangeModel_CatDefault"
local HumanDefault  = "ActionDreamlandMainChangeModel_HumanDefault"
local Cat_2_Human   = "ActionDreamlandMainChangeModel_Cat-Human"
local Human_2_Cat   = "ActionDreamlandMainChangeModel_Human-Cat"





-- ========================================================

function UIMain_SwitchBtn:__init()
    self.controller = nil
end


function UIMain_SwitchBtn:__delete()
    self.co_1 = nil
end



function UIMain_SwitchBtn:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end


function UIMain_SwitchBtn:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.catPanel and self.humanPanel )
    self.changeModeAnimation = KTool.GetComponent( self.controller.gameObject, typeof(Animation) )
    assert( self.changeModeAnimation )

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end


function UIMain_SwitchBtn:DelayInit() 

    -- 先等待一帧, 等新场景中新的 SwitchablePlayer 实例被创建;
    coroutine.yield(Yielders.EndOfFrame)


    local morphologyTypeStr = ""
    self.role = nil -- 它的 pos 就是角色的 pos, 它的 forwatd 方向就是角色的当前运动方向

    for i=0,DreamSpaceStates.DelayInitWaitFrames do
        self.role = GlobalsInDreamSpace.FindComponent("vTargetFollow")
        morphologyTypeStr = GlobalsInDreamSpace.GetStringState("MorphologyType") -- string 
        if (morphologyTypeStr == "Cat" or morphologyTypeStr == "Human") and isNotNull(self.role) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end

    assert( (morphologyTypeStr == "Cat" or morphologyTypeStr == "Human"), "始终没能等到某个 SwitchablePlayerController 实例初始化完成" )
    assert( isNotNull(self.role), "始终没能拿到 vTarget Follow" )

    -- local morphologyTypeStr = GlobalsInDreamSpace.GetStringState("MorphologyType") -- string 
    -- if not (morphologyTypeStr == "Cat" or morphologyTypeStr == "Human") then
    --     printError( "始终没能等到某个 SwitchablePlayerController 实例初始化完成" )
    --     return
    -- end

    ----- set init state:
    local morphologyType = (morphologyTypeStr == "Cat") and RoleMorphologyType.Cat or RoleMorphologyType.Human
    if morphologyType ~= RoleMorphologyType.Cat then
        -- --- init human ---:

        --KTool.SetActive( self.humanPanel.gameObject, true ) -- todo: 临时关闭人物按钮 (attack)
        KTool.SetActive( self.humanPanel.gameObject, false ) -- todo: 临时关闭人物按钮 (attack)
        KTool.SetActive( self.catPanel.gameObject, false )

        --morphologyType = RoleMorphologyType.Human;
        self.changeModeAnimation:Play( HumanDefault )
    
    else 
        -- --- init cat ---:

        KTool.SetActive( self.humanPanel.gameObject, false )
        KTool.SetActive( self.catPanel.gameObject, true )

        --morphologyType = RoleMorphologyType.Cat;
        self.changeModeAnimation:Play( CatDefault )
    end

    -- 绑定监听:
    -- 本脚本内并不绑定 btn, 而是等到 TouchInputSwitchable 中触发 btn, 进而触发这个全局 event
    self.OnSwitchToCat   = Bind( self,  self.SwitchToCat )
    self.OnSwitchToHuman = Bind( self,  self.SwitchToHuman )
    CS.Engine.Modules.EventsModule.AddListener( GameContants.MorphologyToCat,   self.OnSwitchToCat )
    CS.Engine.Modules.EventsModule.AddListener( GameContants.MorphologyToHuman, self.OnSwitchToHuman )

end




function UIMain_SwitchBtn:OnDestroy()

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象

    CS.Engine.Modules.EventsModule.RemoveListener( GameContants.MorphologyToCat,   self.OnSwitchToCat )
    CS.Engine.Modules.EventsModule.RemoveListener( GameContants.MorphologyToHuman, self.OnSwitchToHuman )
    self.OnSwitchToCat = nil
    self.OnSwitchToHuman = nil

    self:Delete()
end

-- =========================================== Self ================================================ --



function UIMain_SwitchBtn:SwitchToCat()
    KTool.SetActive( self.humanPanel.gameObject, false )
    KTool.SetActive( self.catPanel.gameObject, true )
    self.changeModeAnimation:Play( Human_2_Cat )
end


function UIMain_SwitchBtn:SwitchToHuman()
    --KTool.SetActive( self.humanPanel.gameObject, true ) -- todo: 临时关闭人物按钮 (attack)
    KTool.SetActive( self.humanPanel.gameObject, false ) -- todo: 始终关闭人物按钮 (attack)  因为这个功能暂时无用途
    KTool.SetActive( self.catPanel.gameObject, false )
    self.changeModeAnimation:Play( Cat_2_Human )
end



return UIMain_SwitchBtn

